13	/**
14	 * Determine the tick count or interval function.
15	 * @param {Scale} scale - The scale for which to generate tick values.
16	 * @param {*} count - The desired tick count or interval specifier.
17	 * @param {number} minStep - The desired minimum step between tick values.
18	 * @return {*} - The tick count or interval function.
19	 */
20	export function tickCount(scale, count, minStep) {
21	  let step;
22	
23	  if (isNumber(count)) {
24	    if (scale.bins) {
25	      count = Math.max(count, scale.bins.length);
26	    }
27	    if (minStep != null) {
28	      count = Math.min(
29	        count,
30	        Math.floor((span(scale.domain()) / minStep) || 1) + 1
31	      );
32	    }
33	  }
34	
35	  if (isObject(count)) {
36	    step = count.step;
37	    count = count.interval;
38	  }
39	
40	  if (isString(count)) {
41	    count = scale.type === Time ? timeInterval(count)
42	      : scale.type == UTC ? utcInterval(count)
43	      : error('Only time and utc scales accept interval strings.');
44	    if (step) count = count.every(step);
45	  }
46	
47	  return count;
48	}
