50	/**
51	 * Filter a set of candidate tick values, ensuring that only tick values
52	 * that lie within the scale range are included.
53	 * @param {Scale} scale - The scale for which to generate tick values.
54	 * @param {Array<*>} ticks - The candidate tick values.
55	 * @param {*} count - The tick count or interval function.
56	 * @return {Array<*>} - The filtered tick values.
57	 */
58	export function validTicks(scale, ticks, count) {
59	  let range = scale.range(),
60	      lo = range[0],
61	      hi = peek(range),
62	      cmp = ascending;
63	
64	  if (lo > hi) {
65	    range = hi;
66	    hi = lo;
67	    lo = range;
68	    cmp = descending;
69	  }
70	
71	  lo = Math.floor(lo);
72	  hi = Math.ceil(hi);
73	
74	  // filter ticks to valid values within the range
75	  // additionally sort ticks in range order (#2579)
76	  ticks = ticks.map(v => [v, scale(v)])
77	    .filter(_ => lo <= _[1] && _[1] <= hi)
78	    .sort(cmp)
79	    .map(_ => _[0]);
80	
81	  if (count > 0 && ticks.length > 1) {
82	    const endpoints = [ticks[0], peek(ticks)];
83	    while (ticks.length > count && ticks.length >= 3) {
84	      ticks = ticks.filter((_, i) => !(i % 2));
85	    }
86	    if (ticks.length < 3) {
87	      ticks = endpoints;
88	    }
89	  }
90	
91	  return ticks;
92	}
