94	/**
95	 * Generate tick values for the given scale and approximate tick count or
96	 * interval value. If the scale has a 'ticks' method, it will be used to
97	 * generate the ticks, with the count argument passed as a parameter. If the
98	 * scale lacks a 'ticks' method, the full scale domain will be returned.
99	 * @param {Scale} scale - The scale for which to generate tick values.
100	 * @param {*} [count] - The approximate number of desired ticks.
101	 * @return {Array<*>} - The generated tick values.
102	 */
103	export function tickValues(scale, count) {
104	  return scale.bins ? validTicks(scale, scale.bins, count)
105	    : scale.ticks ? scale.ticks(count)
106	    : scale.domain();
