109	/**
110	 * Generate a label format function for a scale. If the scale has a
111	 * 'tickFormat' method, it will be used to generate the formatter, with the
112	 * count and specifier arguments passed as parameters. If the scale lacks a
113	 * 'tickFormat' method, the returned formatter performs simple string coercion.
114	 * If the input scale is a logarithmic scale and the format specifier does not
115	 * indicate a desired decimal precision, a special variable precision formatter
116	 * that automatically trims trailing zeroes will be generated.
117	 * @param {Scale} scale - The scale for which to generate the label formatter.
118	 * @param {*} [count] - The approximate number of desired ticks.
119	 * @param {string} [specifier] - The format specifier. Must be a legal d3
120	 *   specifier string (see https://github.com/d3/d3-format#formatSpecifier) or
121	 *   time multi-format specifier object.
122	 * @return {function(*):string} - The generated label formatter.
123	 */
124	export function tickFormat(locale, scale, count, specifier, formatType, noSkip) {
125	  const type = scale.type;
126	  let format = defaultFormatter;
127	
128	  if (type === Time || formatType === Time) {
129	    format = locale.timeFormat(specifier);
130	  }
131	  else if (type === UTC || formatType === UTC) {
132	    format = locale.utcFormat(specifier);
133	  }
134	  else if (isLogarithmic(type)) {
135	    const varfmt = locale.formatFloat(specifier);
136	    if (noSkip || scale.bins) {
137	      format = varfmt;
138	    } else {
139	      const test = tickLog(scale, count, false);
140	      format = _ => test(_) ? varfmt(_) : '';
141	    }
142	  }
143	  else if (scale.tickFormat) {
144	    // if d3 scale has tickFormat, it must be continuous
145	    const d = scale.domain();
146	    format = locale.formatSpan(d[0], d[d.length - 1], count, specifier);
147	  }
148	  else if (specifier) {
149	    format = locale.format(specifier);
150	  }
151	
152	  return format;
153	}
