155	export function tickLog(scale, count, values) {
156	  const ticks = tickValues(scale, count),
157	        base = scale.base(),
158	        logb = Math.log(base),
159	        k = Math.max(1, base * count / ticks.length);
160	
161	  // apply d3-scale's log format filter criteria
162	  const test = d => {
163	    let i = d / Math.pow(base, Math.round(Math.log(d) / logb));
164	    if (i * base < base - 0.5) i *= base;
165	    return i <= k;
166	  };
167	
168	  return values ? ticks.filter(test) : test;
169	}
